/* Generated by tools/bake_tracks.py from tracks/catalog.json.
 * Each span is one period. Past the lead, path_at repeats the cycle.
 * rep_x, rep_y, rep_z shift the next period. A lap that closes
 * shifts by zero. cycle 0 is a road that ends: past the last
 * segment the deck runs straight on that heading. A branch is a
 * second road over bands band0 to band1, its segments from seg[alt]. */

typedef struct {
    int band0, band1, alt;
} TrackBranch;

typedef struct {
    const char *id;
    const PathSeg *seg;
    int lead;
    int cycle;
    int count;
    int rep_x, rep_y, rep_z;
    const TrackBranch *branch;
    int branches;
} TrackDef;

